// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY, LogFile} from "../src/PENNY_BY_PENNY.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    Attacker attacker;
    LogFile logf;

    function setUp() public {
        c = new PENNY_BY_PENNY();
        // deploy a real LogFile and set it
        logf = new LogFile();
        // initialize c: must call SetLogFile and SetMinSum before Initialized
        c.SetLogFile(address(logf));
        c.SetMinSum(1);
        // do not call Initialized() so Set* remain allowed in other tests if needed
    }

    // fuzzed params: attacker deposit amount, withdraw request amount, lockTime
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt, uint256 lockTime) public {
        vm.assume(depositAmt <= VALUE_CAP);
        // keep amounts within payable practical bounds
        depositAmt = bound(depositAmt, 1, 1 ether);
        withdrawAmt = bound(withdrawAmt, 1, 1 ether);
        lockTime = bound(lockTime, 0, 1000);

        // deploy attacker that will reenter exactly once when receiving funds
        attacker = new Attacker(c);

        // fund attacker so it can call Put
        vm.deal(address(attacker), depositAmt);

        // attacker puts funds into c; Put is payable
        attacker.doPut{value: depositAmt}(lockTime);

        // record balance before Collect
        (uint beforeUnlockTime, uint beforeBal) = c.Acc(address(attacker));

        // ensure conditions to allow Collect succeed path where possible:
        // MinSum was set to 1 in setUp; ensure acc.balance >= MinSum by deposit above
        // ensure withdrawAmt bounded already; advance time past unlockTime so Collect won't fail due to time
        vm.warp(block.timestamp + lockTime + 1);

        // perform Collect via attacker which will attempt to reenter once during the low-level call
        bool ok;
        // give c some gas balance to pay out
        vm.deal(address(c), 2 ether);

        try attacker.callCollect(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // read recorded balance after Collect
        (uint afterUnlockTime, uint afterBal) = c.Acc(address(attacker));

        // The universal property: if the reference contract returns normally (ok == true), then the decrease
        // in the caller's balance is at most withdrawAmt. If the reference reverts, ok == false is allowed.
        // This single assert distinguishes the mutant which (when reentrancy guard removed) can make ok==true
        // yet withdraw more than withdrawAmt in a single Collect call.
        if (ok) {
            // afterBal >= beforeBal - withdrawAmt  <=> beforeBal - afterBal <= withdrawAmt
            assertTrue(beforeBal - afterBal <= withdrawAmt);
        } else {
            // if reference reverts, that's valid universal behavior; assert that nothing invalid is observed
            assertTrue(beforeBal >= afterBal);
        }
    }
}

// Attacker that records and reenters exactly once on receive to attempt to exploit reentrancy
contract Attacker {
    PENNY_BY_PENNY c;
    bool private entered;

    constructor(PENNY_BY_PENNY _c) {
        c = _c;
        entered = false;
    }

    // deposit into c
    function doPut(uint _lockTime) external payable {
        // call Put as this contract
        c.Put{value: msg.value}(_lockTime);
    }

    // entry to trigger Collect from this contract; will receive funds and attempt one reentrant Collect
    function callCollect(uint _am) external {
        // call Collect on c as this contract
        c.Collect{value: 0}(_am);
    }

    // when c sends value back, this receive will try to reenter Collect exactly once
    receive() external payable {
        if (!entered) {
            entered = true;
            // attempt reentrant Collect which should be blocked by reference but allowed by mutant
            // call with zero value here; any args are fuzzed in the top-level test
            // Use a small withdraw amount to not exceed contract balance
            // Note: we intentionally call the same Collect function to attempt to drain more
            // Use gas stipend available to attempt the reentry
            // We pick a nominal amount of 1 wei for the reentrant attempt; the overall test's distinguishing
            // behavior arises when mutant allows this reentry to succeed and withdraw extra funds.
            // We ignore errors to let outer call proceed accordingly.
            try c.Collect{value: 0}(1) {
            } catch {
            }
        }
    }
}
